import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/cyclehire_w003.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute the Self-Containment Index for each borough
boroughs = df['StartBorough'].unique()
self_containment_index = {}

for borough in boroughs:
    departures = len(df[df['StartBorough'] == borough])
    self_contained_trips = len(df[(df['StartBorough'] == borough) & (df['EndBorough'] == borough)])
    arrival_share = len(df[df['EndBorough'] == borough]) / len(df)
    expected_self_contained_trips = departures * arrival_share
    self_containment_index[borough] = self_contained_trips / expected_self_contained_trips

# Print the Self-Containment Index for each borough
for borough, index in self_containment_index.items():
    print(f'Borough: {borough}, Self-Containment Index: {index}')

# Load the adjacency list
adjacency_list = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in adjacency_list:
        adjacency_list[row['borough']] = []
    adjacency_list[row['borough']].append(row['neighbor'])

# Create a dictionary to store the Self-Containment Index values for each borough
self_containment_values = {borough: index for borough, index in self_containment_index.items()}

# Create a dictionary to store the neighboring boroughs for each borough
neighbor_boroughs = {}
for borough, neighbors in adjacency_list.items():
    for neighbor in neighbors:
        if neighbor not in neighbor_boroughs:
            neighbor_boroughs[neighbor] = []
        neighbor_boroughs[neighbor].append(borough)

# Create a list to store the Self-Containment Index values for each neighboring borough
neighbor_values = []
for neighbor, boroughs in neighbor_boroughs.items():
    for borough in boroughs:
        neighbor_values.append(self_containment_values[neighbor])

# Compute the Moran's I statistic
n = len(self_containment_values)
x_bar = np.mean(list(self_containment_values.values()))
s = 0
for value in list(self_containment_values.values()):
    s += (value - x_bar) ** 2
s = s / (n - 1)
s2 = 0
for i in range(n):
    for j in range(i + 1, n):
        s2 += (neighbor_values[i] - x_bar) * (neighbor_values[j] - x_bar)
s2 = s2 / (n * (n - 1))
morans_i = (n * s2 - s) / (n * s)
print(f'Moran\'s I statistic: {morans_i}')

# Compute the p-value using a permutation test
p_value = 0
for _ in range(500):
    neighbor_values_perm = np.random.permutation(neighbor_values)
    s_perm = 0
    for i in range(n):
        for j in range(i + 1, n):
            s_perm += (neighbor_values_perm[i] - x_bar) * (neighbor_values_perm[j] - x_bar)
    s_perm = s_perm / (n * (n - 1))
    morans_i_perm = (n * s_perm - s)
    if morans_i_perm >= morans_i:
        p_value += 1
p_value = p_value / 500
print(f'p-value: {p_value}')

# Print the final answer
if morans_i > 0:
    print(f'FINAL ANSWER: CLUSTERED (statistical method = Moran\'s I, p = {p_value})')
else:
    print(f'FINAL ANSWER: NOT CLUSTERED (statistical method = Moran\'s I, p = {p_value})')
